/**
 * Returns {lat, lng} coordinates for a stopId or null if not found.
 */
export function stopCoords(stopId) {
  return STOP_COORDS[stopId] || null;
}

/**
 * Returns the [lat, lng] array of road geometry points for tripId or null if not found.
 */
// A schedule the company added drives the road of the schedule it was made from (D128).
const SHAPE_ALIASES = new Map();
export function aliasShape(scheduleId, sourceId) {
  if (sourceId && sourceId !== scheduleId) SHAPE_ALIASES.set(scheduleId, sourceId);
}

export function routeShape(tripId) {
  // A day's run (`trp_hn_th_01_20261015`) drives the road of its schedule.
  const id = String(tripId);
  const schedule = id.replace(/_\d{8}$/, '');
  return ROUTE_SHAPES[id] || ROUTE_SHAPES[schedule] || ROUTE_SHAPES[SHAPE_ALIASES.get(schedule)] || null;
}

/**
 * Projects a point onto the road shape using equirectangular projection per segment.
 */
export function projectOnShape(shape, lat, lng) {
  if (!Array.isArray(shape) || shape.length === 0) return null;
  if (shape.length === 1) {
    return {
      along_m: 0,
      offset_m: calculateHaversineDistance(lat, lng, shape[0][0], shape[0][1]),
      index: 0
    };
  }

  let cumDist = 0;
  let bestAlong = 0;
  let bestOffset = Infinity;
  let bestIndex = 0;

  for (let i = 0; i < shape.length - 1; i++) {
    const p1 = shape[i];
    const p2 = shape[i + 1];
    const segLen = calculateHaversineDistance(p1[0], p1[1], p2[0], p2[1]);

    const midLatRad = ((p1[0] + p2[0]) / 2) * (Math.PI / 180);
    const cosLat = Math.cos(midLatRad);
    const dx = (p2[1] - p1[1]) * cosLat;
    const dy = p2[0] - p1[0];
    const px = (lng - p1[1]) * cosLat;
    const py = lat - p1[0];

    const len2 = dx * dx + dy * dy;
    let t = len2 > 0 ? (px * dx + py * dy) / len2 : 0;
    t = Math.max(0, Math.min(1, t));

    const projLat = p1[0] + t * (p2[0] - p1[0]);
    const projLng = p1[1] + t * (p2[1] - p1[1]);
    const offset = calculateHaversineDistance(lat, lng, projLat, projLng);

    if (offset < bestOffset) {
      bestOffset = offset;
      bestAlong = cumDist + t * segLen;
      bestIndex = i;
    }
    cumDist += segLen;
  }

  return {
    along_m: Math.round(bestAlong),
    offset_m: Math.round(bestOffset),
    index: bestIndex
  };
}

/**
 * Calculates signed distance in meters along the road shape between two points.
 * Negative when the target is behind the starting point.
 */
export function signedDistanceAlongRoute(shape, fromLat, fromLng, toLat, toLng) {
  const fromProj = projectOnShape(shape, fromLat, fromLng);
  const toProj = projectOnShape(shape, toLat, toLng);
  if (!fromProj || !toProj) return null;
  if (fromProj.offset_m > 2000 || toProj.offset_m > 2000) return null;
  return Math.round(toProj.along_m - fromProj.along_m);
}

/**
 * Calculates distance in meters along the road shape between two points.
 */
export function distanceAlongRoute(shape, fromLat, fromLng, toLat, toLng) {
  const signed = signedDistanceAlongRoute(shape, fromLat, fromLng, toLat, toLng);
  if (signed === null) return null;
  return Math.max(0, signed);
}
